+     * Root directory containing all the files generated by this task. It is
+     * contained within testRoot.
+     */
+    @OutputDirectory
+    File getOutputRoot() {
+        return new File(getTestRoot().get().getAsFile(), "/rest-api-spec/test");
+    }
