timeline.body:
I wrote a few tests to convince myself that stats from pipelines other than the first are getting recorded. Specifically, if there is a pipeline called from a pipeline processor, if there is a final pipeline, or if there is a pipeline from a reroute (the case I was most worried about).  For all three tests the initial pipeline is a noop. All three tests pass! Could you add these to this yaml file? 

```
---
"Test that pipeline processor has byte stats recorded in first pipeline":
  - do:
      ingest.put_pipeline:
        id: "pipeline-1"
        body:  >
          {
            "processors": [
              {
                "pipeline": {
                  "name": "pipeline-2"
                }
              }
            ]
          }
  - do:
      ingest.put_pipeline:
        id: "pipeline-2"
        body:  >
          {
            "processors": [
              {
                "set" : {
                  "field": "added-in-second-pipeline",
                  "value": "foo bar baz"
                }
              }
            ]
          }
  - do:
      indices.create:
        index: an-index
        body:
          settings:
            index:
              default_pipeline: "pipeline-1"
  - do:
      bulk:
        refresh: true
        index: index-foo
        body:
          - '{"index": { "_index": "an-index", "_id": 1 }}'
          - '{"some-field": 1 }'
  - do:
      get:
        id: 1
        index: an-index
  - match: { _source.added-in-second-pipeline: "foo bar baz" }

  - do:
      cluster.info:
        target: [ ingest ]
  - gt: { ingest.pipelines.pipeline-1.ingested_in_bytes: 0 }
  - set: { ingest.pipelines.pipeline-1.ingested_in_bytes: ingest_bytes }
  - gt: { ingest.pipelines.pipeline-1.produced_in_bytes: $ingest_bytes }
  - match: { ingest.pipelines.pipeline-2.ingested_in_bytes: null }
  - match: { ingest.pipelines.pipeline-2.produced_in_bytes: null }

---
"Test that final pipeline has byte stats recorded in first pipeline":
  - do:
      ingest.put_pipeline:
        id: "pipeline-1"
        body:  >
          {
            "processors": []
          }
  - do:
      ingest.put_pipeline:
        id: "pipeline-2"
        body:  >
          {
            "processors": [
              {
                "set" : {
                  "field": "added-in-second-pipeline",
                  "value": "foo bar baz"
                }
              }
            ]
          }
  - do:
      indices.create:
        index: an-index
        body:
          settings:
            index:
              default_pipeline: "pipeline-1"
              final_pipeline: "pipeline-2"
  - do:
      bulk:
        refresh: true
        index: index-foo
        body:
          - '{"index": { "_index": "an-index", "_id": 1 }}'
          - '{"some-field": 1 }'
  - do:
      get:
        id: 1
        index: an-index
  - match: { _source.added-in-second-pipeline: "foo bar baz" }

  - do:
      cluster.info:
        target: [ ingest ]
  - gt: { ingest.pipelines.pipeline-1.ingested_in_bytes: 0 }
  - set: { ingest.pipelines.pipeline-1.ingested_in_bytes: ingest_bytes }
  - gt: { ingest.pipelines.pipeline-1.produced_in_bytes: $ingest_bytes }
  - match: { ingest.pipelines.pipeline-2.ingested_in_bytes: null }
  - match: { ingest.pipelines.pipeline-2.produced_in_bytes: null }


---
"Test that reroute processor has byte stats recorded in first pipeline":
  - do:
      ingest.put_pipeline:
        id: "pipeline-1"
        body:  >
          {
            "processors": [
              {
                "reroute": {
                  "destination": "index-2"
                }
              }
            ]
          }
  - do:
      ingest.put_pipeline:
        id: "pipeline-2"
        body:  >
          {
            "processors": [
              {
                "set" : {
                  "field": "added-in-second-pipeline",
                  "value": "foo bar baz"
                }
              }
            ]
          }
  - do:
      indices.create:
        index: index-1
        body:
          settings:
            index:
              default_pipeline: "pipeline-1"
  - do:
      indices.create:
        index: index-2
        body:
          settings:
            index:
              default_pipeline: "pipeline-2"
  - do:
      bulk:
        refresh: true
        index: index-1
        body:
          - '{"index": { "_index": "index-1", "_id": 1 }}'
          - '{"some-field": 1 }'
  - do:
      get:
        id: 1
        index: index-2
  - match: { _source.added-in-second-pipeline: "foo bar baz" }

  - do:
      cluster.info:
        target: [ ingest ]
  - gt: { ingest.pipelines.pipeline-1.ingested_in_bytes: 0 }
  - set: { ingest.pipelines.pipeline-1.ingested_in_bytes: ingest_bytes }
  - gt: { ingest.pipelines.pipeline-1.produced_in_bytes: $ingest_bytes }
  - match: { ingest.pipelines.pipeline-2.ingested_in_bytes: null }
  - match: { ingest.pipelines.pipeline-2.produced_in_bytes: null }

```

